// One item, one report, for whichever of the five QRSalt events arrived.
//
// Same rule as the full test: this may only say PASSED when a delivery really
// arrived carrying the fields that event is supposed to carry. An empty body,
// an event nobody subscribed to, or a payload naming no code or form is a
// failure and says which. A report that says "ok" when nothing happened is
// worse than no report.
//
// Run Once for All Items, so the delivery is read off the input.

// What each event carries, from the QRSalt webhook contract:
//   scan.recorded   data.codeId, slug, scannedAt, country, regionCode, city, device, os, browser, referrerHost
//   code.created    data.id, slug, name, kind, type, destination
//   code.updated    data.id, slug, and whatever changed (previousDestination/destination, customUrl, gs1Url, utm, domain)
//   code.disabled   data.id, slug, from, status
//   form.submitted  data.formId, slug, title, responseId, version, submittedAt, country, score, answers[]
// Only the fields every delivery of that event must have are required here.
const EVENTS = {
  'scan.recorded': { says: 'a code or short link was scanned', needs: ['codeId'], about: 'code' },
  'code.created': { says: 'a code or short link was made', needs: ['id'], about: 'code' },
  'code.updated': { says: 'a code was re-pointed', needs: ['id'], about: 'code' },
  'code.disabled': { says: 'a code was paused, deleted or disabled', needs: ['id'], about: 'code' },
  'form.submitted': { says: 'a QR Form was answered', needs: ['formId', 'responseId'], about: 'form' },
};
const ALL = Object.keys(EVENTS);

let body = {};
try {
  const first = $input.first();
  body = (first && first.json) || {};
} catch (e) {
  body = {};
}

const keys = Object.keys(body);
const data = body.data && typeof body.data === 'object' && !Array.isArray(body.data) ? body.data : {};
const event = body.event ?? null;
const known = event && Object.prototype.hasOwnProperty.call(EVENTS, event) ? EVENTS[event] : null;

const failures = [];
const lines = [];
const oneLine = (s, n) => String(s).replace(/\s+/g, ' ').trim().slice(0, n || 160);
const v = (x) => (x === undefined || x === null || x === '' ? 'MISSING' : String(x));
const set = (x) => x !== undefined && x !== null && x !== '';

if (keys.length === 0) {
  failures.push('the delivery arrived with an empty body — nothing was sent, or it was not JSON');
} else if (!set(event)) {
  failures.push('no "event" field in the delivery, so there is no way to tell what happened');
} else if (!known) {
  failures.push(
    'the delivery is for "' + oneLine(event, 60) + '", which is not one of the five events this trigger subscribes to',
  );
} else {
  for (const field of known.needs) {
    if (!set(data[field])) {
      failures.push(
        event + ' arrived without data.' + field + ', so it names no ' + known.about + ' and cannot be traced back to one',
      );
    }
  }
}

// Every delivery carries these two, whatever the event. Without the id a repeat
// cannot be recognised, and delivery is at-least-once.
if (keys.length > 0 && !set(body.id)) {
  failures.push('the delivery carries no event id, so a repeat of it could not be told from a new event');
}
if (keys.length > 0 && !set(body.createdAt)) {
  failures.push('the delivery carries no createdAt, so there is no telling when the event happened');
}

// What it is about, in the words the dashboard uses.
let subject = 'MISSING';
if (known && known.about === 'form') {
  const answers = Array.isArray(data.answers) ? data.answers.length : null;
  subject =
    'form ' +
    v(data.formId) +
    (set(data.title) ? ' "' + oneLine(data.title, 60) + '"' : '') +
    ', response ' +
    v(data.responseId) +
    (answers === null ? '' : ' (' + answers + ' answer' + (answers === 1 ? '' : 's') + ')');
} else if (known) {
  subject = 'code ' + v(data.codeId ?? data.id) + (set(data.slug) ? ' (/' + data.slug + ')' : '');
}

// A test delivery from Settings → Webhooks is a real signed delivery with
// made-up contents, so it passes — but it is labelled, because it proves the
// plumbing and not that your code fired the event.
const isTest = data.test === true || String(body.id ?? '').startsWith('evt_test_');

// Which of the five have been seen since the workflow was switched on. Static
// data is saved after a production execution, so this is a running checklist.
let seen = [];
let tracked = false;
try {
  if (typeof $getWorkflowStaticData === 'function') {
    const store = $getWorkflowStaticData('global') || {};
    const list = Array.isArray(store.eventsSeen) ? store.eventsSeen.filter((e) => ALL.includes(e)) : [];
    if (known && failures.length === 0 && !list.includes(event)) list.push(event);
    store.eventsSeen = list;
    seen = list;
    tracked = true;
  }
} catch (e) {
  tracked = false;
}
const left = ALL.filter((e) => !seen.includes(e));

lines.push('event:          ' + v(event) + (known ? '  (' + known.says + ')' : ''));
lines.push('about:          ' + subject);
lines.push('event id:       ' + v(body.id) + (isTest ? '  — a test delivery from Settings → Webhooks' : ''));
lines.push('event time:     ' + v(body.createdAt));
lines.push(
  'signature:      verified — the trigger answers 401 and does not start the workflow when the check fails, so this execution existing is the proof',
);
lines.push('delivery:       at-least-once — the same event id can arrive twice, so dedupe on it before acting');
lines.push('data fields:    ' + (Object.keys(data).length ? Object.keys(data).join(', ') : 'NONE — data was empty'));
lines.push(
  'events so far:  ' +
    (!tracked
      ? 'not tracked in this run'
      : (seen.length ? seen.join(', ') : 'none yet') + (left.length ? '   still to fire: ' + left.join(', ') : '   — all five done')),
);

let payload = '';
try {
  payload = JSON.stringify(body).slice(0, 1200);
} catch (e) {
  payload = '(could not be printed: ' + oneLine(e.message, 80) + ')';
  failures.push('the delivery could not be serialised: ' + oneLine(e.message, 80));
}

const passed = failures.length === 0;
const result = passed
  ? 'PASSED — signed ' + event + ' delivery for ' + subject + (isTest ? ' (test event)' : '')
  : 'FAILED — ' + failures[0];

const report = [
  passed
    ? 'RESULT: PASSED — a signed ' + event + ' delivery arrived, about ' + subject
    : 'RESULT: FAILED — ' + failures.length + ' problem' + (failures.length === 1 ? '' : 's') + ' with this delivery',
  'QRSalt trigger — delivery received ' + new Date().toISOString(),
  ''.padEnd(72, '-'),
  ...lines,
  ''.padEnd(72, '-'),
  'FAILURES: ' + (failures.length ? failures.length : 'none'),
  ...failures.map((f) => '  - ' + f),
  'PAYLOAD:',
  '  ' + payload,
].join('\n');

return [{ json: { result, passed, event, subject, isTest, report } }];

// This branch only. Every other branch gets no items at all, so the execution
// shows at a glance which event arrived.
const WANTED = 'scan.recorded';
return $input.all().filter((item) => item.json.event === WANTED);

// This branch only. Every other branch gets no items at all, so the execution
// shows at a glance which event arrived.
const WANTED = 'code.created';
return $input.all().filter((item) => item.json.event === WANTED);

// This branch only. Every other branch gets no items at all, so the execution
// shows at a glance which event arrived.
const WANTED = 'code.updated';
return $input.all().filter((item) => item.json.event === WANTED);

// This branch only. Every other branch gets no items at all, so the execution
// shows at a glance which event arrived.
const WANTED = 'code.disabled';
return $input.all().filter((item) => item.json.event === WANTED);

// This branch only. Every other branch gets no items at all, so the execution
// shows at a glance which event arrived.
const WANTED = 'form.submitted';
return $input.all().filter((item) => item.json.event === WANTED);

// Anything the trigger delivered that is not one of the five. An item here
// means QRSalt sent an event this workflow did not ask for, or the node's event
// list and the API's have drifted apart.
const KNOWN = ['scan.recorded', 'code.created', 'code.updated', 'code.disabled', 'form.submitted'];
return $input.all().filter((item) => !KNOWN.includes(item.json.event));
